{
  "name": "codex-computer-use-mcp",
  "version": "0.7.1",
  "description": "Give Pi and MCP clients the official macOS Computer Use runtime that ChatGPT uses, without a nested model.",
  "author": "Thomas Mustier",
  "license": "MIT",
  "type": "module",
  "os": [
    "darwin"
  ],
  "keywords": [
    "computer-use",
    "macos",
    "automation",
    "pi-package",
    "mcp"
  ],
  "publishConfig": {
    "access": "public"
  },
  "pi": {
    "extensions": [
      "./integrations/pi/index.ts"
    ]
  },
  "bin": {
    "codex-computer-use-mcp": "dist/mcp-server.js"
  },
  "files": [
    "dist",
    "src",
    "integrations/pi",
    "README.md",
    "SECURITY.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json",
    "lint": "oxlint --deny-warnings",
    "check": "npm run lint && tsc -p tsconfig.json --noEmit",
    "pretest": "npm run build",
    "test": "node --test test/*.test.ts test/legacy/*.test.ts",
    "prepare": "npm run build",
    "prepublishOnly": "npm run check && npm run check:pi && npm test",
    "check:pi": "npx tsc --ignoreConfig --noEmit --target ES2022 --module NodeNext --moduleResolution NodeNext --strict --skipLibCheck --allowImportingTsExtensions --types node integrations/pi/index.ts"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "1.32.1",
    "zod": "4.4.3"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": ">=0.99.0"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "1.2.0",
    "@oxlint/plugins": "1.79.0",
    "@types/node": "24.13.3",
    "oxlint": "1.79.0",
    "typescript": "7.0.2"
  },
  "engines": {
    "node": ">=22"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tmustier/codex-computer-use-mcp.git"
  },
  "bugs": {
    "url": "https://github.com/tmustier/codex-computer-use-mcp/issues"
  },
  "homepage": "https://github.com/tmustier/codex-computer-use-mcp#readme"
}
